// MinimockWriteTupleInspect logs each unmet expectation
func (m *PermissionServiceClientMock) MinimockWriteTupleInspect() {
	for _, e := range m.WriteTupleMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to PermissionServiceClientMock.WriteTuple at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterWriteTupleCounter := mm_atomic.LoadUint64(&m.afterWriteTupleCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.WriteTupleMock.defaultExpectation != nil && afterWriteTupleCounter < 1 {
		if m.WriteTupleMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to PermissionServiceClientMock.WriteTuple at\n%s", m.WriteTupleMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to PermissionServiceClientMock.WriteTuple at\n%s with params: %#v", m.WriteTupleMock.defaultExpectation.expectationOrigins.origin, *m.WriteTupleMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcWriteTuple != nil && afterWriteTupleCounter < 1 {
		m.t.Errorf("Expected call to PermissionServiceClientMock.WriteTuple at\n%s", m.funcWriteTupleOrigin)
	}

	if !m.WriteTupleMock.invocationsDone() && afterWriteTupleCounter > 0 {
		m.t.Errorf("Expected %d calls to PermissionServiceClientMock.WriteTuple at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.WriteTupleMock.expectedInvocations), m.WriteTupleMock.expectedInvocationsOrigin, afterWriteTupleCounter)
	}
}

